//! Offline fresh INITIAL deployment proof. No HTTP client, secrets or update.
use anyhow::{ensure,Result};use std::{env,fs,io::Write,path::Path,time::Instant};use sha2::{Digest,Sha256};use plonky2::field::goldilocks_field::GoldilocksField as F;use psy_client_common::data::qhashout::QHashOut;use psy_client_data::config::store_config::PsyHasher;use psy_provider::request::QDeployContractRPCRequest;use psy_template_u124_markets::layout_preflight;
fn save(p:&Path,v:&impl serde::Serialize)->Result<()>{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(p)?;f.write_all(&serde_json::to_vec_pretty(v)?)?;f.sync_all()?;Ok(())}
fn main()->Result<()>{let a=env::args().collect::<Vec<_>>();ensure!(a.len()==4,"ARTIFACT EXPECTED_DEPLOYER FRESH_DIRECTORY");let start=Instant::now();let bytes=fs::read(&a[1])?;let artifact=serde_json::from_slice(&bytes)?;let deployer:u64=a[2].parse().map_err(|_|anyhow::anyhow!("invalid deployer"))?;let out=Path::new(&a[3]);fs::create_dir(out)?;fs::File::open(out.parent().unwrap_or(Path::new(".")))?.sync_all()?;let prepared=layout_preflight::prepare_initial(artifact,deployer)?;let artifact=serde_json::from_slice(&bytes)?;let mut report=layout_preflight::verify_initial(&artifact,&prepared,deployer)?;report["functionTreeRoot"]=serde_json::json!(prepared.deploy_contract.clone().into_with_whitelist_root::<PsyHasher>()?.function_whitelist_root.to_string());let request=QDeployContractRPCRequest{deploy_contract:prepared};save(&out.join("request.json"),&request)?;report["artifactSha256"]=serde_json::json!(format!("{:x}",Sha256::digest(&bytes)));report["requestSha256"]=serde_json::json!(format!("{:x}",Sha256::digest(fs::read(out.join("request.json"))?)));report["broadcast"]=serde_json::json!(false);report["offlineProofMilliseconds"]=serde_json::json!(start.elapsed().as_millis() as u64);save(&out.join("preflight.json"),&report)?;fs::File::open(out)?.sync_all()?;Ok(())}
